// newMonkeyMock creates a new instance of monkeyMock. It also registers a testing interface on the mock and a cleanup function to assert the mocks expectations.
// The first argument is typically a *testing.T value.
func newMonkeyMock(t interface {
	mock.TestingT
	Cleanup(func())
}) *monkeyMock {
	mock := &monkeyMock{}
	mock.Mock.Test(t)

	t.Cleanup(func() { mock.AssertExpectations(t) })

	return mock
}
